python - <<'EOF'
import re
p = "catalog/service.py"
s = open(p).read()

s = s.replace("import uuid\n", "import json\nimport uuid\n", 1)

s = s.replace(
    "    def list(self) -> list[dict]:\n        return [dict(r) for r in self._records.values()]\n",
    '''    def list(self) -> list[dict]:
        return [dict(r) for r in self._records.values()]

    def find(self, substring: str) -> list[dict]:
        """Records whose title contains ``substring`` (case-insensitive), in creation order."""
        needle = substring.casefold()
        return [dict(r) for r in self._records.values() if needle in r["title"].casefold()]

    def export(self) -> str:
        """Serialize all records as a JSON array in creation order."""
        return json.dumps(self.list())

    def import_(self, dump: str) -> None:
        """Load records from an ``export()`` dump, keeping their ids.

        The dump is validated in full before anything is inserted, so a bad
        dump leaves the catalog unchanged. Raises ``ValueError`` if the dump is
        malformed or if any id already exists in this catalog.
        """
        try:
            data = json.loads(dump)
        except json.JSONDecodeError as exc:
            raise ValueError(f"invalid JSON dump: {exc}") from None
        if not isinstance(data, list):
            raise ValueError("dump must be a JSON array of records")

        incoming: dict[str, dict] = {}
        for i, item in enumerate(data):
            if not isinstance(item, dict) or set(item) != _RECORD_FIELDS:
                raise ValueError(f"record {i}: expected keys {sorted(_RECORD_FIELDS)}")
            if not all(isinstance(item[k], str) for k in _RECORD_FIELDS):
                raise ValueError(f"record {i}: all fields must be strings")
            rid = item["id"]
            if not rid:
                raise ValueError(f"record {i}: id must be non-empty")
            if rid in incoming or rid in self._records:
                raise ValueError(f"record {i}: duplicate id {rid!r}")
            incoming[rid] = {"id": rid, "title": item["title"], "author": item["author"]}

        self._records.update(incoming)
''',
    1,
)

s = s.replace(
    '_MUTABLE_FIELDS = frozenset({"title", "author"})\n',
    '_MUTABLE_FIELDS = frozenset({"title", "author"})\n_RECORD_FIELDS = frozenset({"id", "title", "author"})\n',
    1,
)
open(p, "w").write(s)
EOF
python -m pytest -q && python - <<'EOF'
from catalog.service import Catalog
c = Catalog(); a = c.create("A", "x")
d = Catalog(); d.import_(c.export()); 
for bad in ['{}', '[1]', '[{"id":"","title":"t","author":"a"}]', c.export()]:
    try: d.import_(bad); print("NO ERROR for", bad)
    except ValueError as e: print("ok:", e)
print(d.list())
EOF

